import {CHECKED_AT,scheduleMeta,fieldStatusLabel} from './official-schedule.js';
import {sourceHtml,eventSourceHtml,futureHtml} from './schedule-ui.js';
export function renderDetailDates({id,meta,ownEvents,params,key,dateText,formatDate,eventLabel,esc}){
 const verified=scheduleMeta[id],today=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Tokyo',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
 const dateRow=e=>`<p class="ed-date-note"><strong>${esc(eventLabel(e))}</strong></p><p class="ed-date-value">${dateText(e)}</p>${e.note?`<p class="ed-date-note">${esc(e.note)}</p>`:''}`;
 const dateCard=type=>{
  const list=ownEvents.filter(e=>e.type===type),upcoming=list.filter(e=>e.date>=today);const shown=list.length>4?(upcoming.length?upcoming.slice(0,3):list.slice(-3)):list;const rest=list.filter(e=>!shown.includes(e));
  let status=verified.fieldSummaries?.[type]||fieldStatusLabel(verified.fields[type]);
  if(verified.fields[type]==='rolling')status=type==='result'?'受検日・受検月ごとに異なります':type==='deadline'?'予約する日時・会場により異なります':'日時・会場を選んで受験';
  return `<article class="ed-date-card ${type}"><h3>${type==='deadline'?'申し込みの締切':type==='exam'?'試験日':meta.resultLabel}</h3>${shown.length?shown.map(dateRow).join(''):`<p class="ed-date-missing">${esc(status)}</p>`}${rest.length?`<details class="ed-more-dates"><summary>ほかの日程も見る（全${list.length}件）</summary>${rest.map(dateRow).join('')}</details>`:''}${verified.fieldNotes?.[type]?`<p class="ed-date-note">${esc(verified.fieldNotes[type])}</p>`:''}${list.length?[...new Set(list.map(e=>e.sourceId))].map(s=>eventSourceHtml(list.find(e=>e.sourceId===s))).join(''):sourceHtml(id,verified.fieldSourceIds?.[type])}</article>`;
 };
 const isUnverified=Object.values(verified.fields).includes('unverified'),hasDates=ownEvents.length>0;
 const application=verified.application?.length||verified.applicationNote?`<div class="ed-application"><h3>申し込みの開始・受付の案内</h3>${(verified.application||[]).map(a=>`<p><strong>${esc(a.label)}</strong>　${a.start?formatDate(a.start,true):''}${a.time?' '+a.time:''}${a.start?'から':''}</p>`).join('')}${verified.applicationNote?`<p>${esc(verified.applicationNote)}</p>`:''}</div>`:'';
 const availability=verified.availability?`<section class="ed-availability"><h3>受ける日時を予約する試験です</h3><p>${esc(verified.availability.note)}</p>${verified.availability.suspensions?.length?`<h4>公表されている休止期間</h4><ul>${verified.availability.suspensions.map(s=>`<li><strong>${formatDate(s.start,true)}から${s.end?formatDate(s.end,true)+'まで':'（終了の具体日は未発表）'}</strong><p>${esc(s.note||'')}</p></li>`).join('')}</ul>`:''}${verified.examWindows?.length?`<details><summary>月ごとの実施期間・結果発表日を見る</summary><div class="ed-window-table tablewrap"><table><thead><tr><th>予約できる実施期間</th><th>結果発表</th></tr></thead><tbody>${verified.examWindows.map(w=>`<tr><td>${formatDate(w.start,true)}〜${formatDate(w.end,true)}</td><td>${w.result?formatDate(w.result,true):'公式案内で確認'}</td></tr>`).join('')}</tbody></table></div></details>`:''}${sourceHtml(id)}</section>`:'';
 return `<section class="ed-dates" id="${key('dates')}" aria-labelledby="${key('dates-title')}"><div class="ed-section-title"><div><span class="ed-kicker">まずは、日程を確認</span><h2 id="${key('dates-title')}">受ける日と、申し込みの期限</h2></div><span class="ed-sample-tag">${isUnverified?'確認できた情報のみ掲載':hasDates?'確認済み':'公表状況・受験方式をご案内'}</span></div><p class="small-note">掲載対象：${esc(verified.scope)} ／ 確認日：${(verified.checkedAt||CHECKED_AT).replaceAll('-','/')}（時刻は日本時間）</p>${meta.status?`<p class="ed-status">${meta.status}。次年度の日程とは別です。</p>`:''}<div class="ed-date-cards">${['deadline','exam','result'].map(dateCard).join('')}</div>${application}${availability}<p class="ed-disclaimer">${esc(verified.notes||'')}</p>${verified.field==='大学入試'&&id!=='kyotsu'?'<p class="small-note">国立大学の出願期間と日程の流れは<a href="/kokkoritsu/">国立大学の入試日程と出願期間</a>に、前期日程と後期日程の違いは<a href="/zenki-koki/">前期と後期の違い</a>にまとめています。</p>':''}${verified.field==='高校入試'?'<p class="small-note">ほかの都道府県の日程は、<a href="/koko/">公立高校入試の都道府県別の日程</a>で見られます。</p>':''}${id==='takken'?'<p class="small-note">勉強の進め方は、<a href="/takken-junbi/">宅建の試験日までの準備</a>にまとめています。</p>':''}${id==='koko-hyogo'?'<p class="small-note">出願の締切と追検査の動き方は、<a href="/hyogo-koko-nyushi-2027/">兵庫県の公立高校入試の日程</a>にまとめています。</p>':''}${['koko-fukuoka','koko-saga','koko-nagasaki','koko-kumamoto','koko-oita','koko-miyazaki','koko-kagoshima','koko-okinawa'].includes(id)?'<p class="small-note">近くの県と出願の締切や検査日を比べるときは、<a href="/kyushu-koko-nyushi-2027/">九州・沖縄の公立高校入試の比較</a>が使えます。</p>':''}${id==='koko-chiba'?'<p class="small-note">受付時間と第2次募集の日は、<a href="/chiba-koko-nyushi-2027/">千葉県の公立高校入試の日程</a>にまとめています。</p>':''}${String(id).startsWith('kanken')?'<p class="small-note">結果が届く日と同じ日に受けられる級は、<a href="/kanken-goukaku-happyo-2026/">漢検2026年度の合格発表と第3回の申込</a>にまとめています。</p>':''}${String(id).startsWith('koko-')?'<p class="small-note">ほかの都道府県の発表日は、<a href="/koko-goukaku-happyo-2027/">公立高校の合格発表日の一覧</a>で比べられます。</p>':''}${String(id).startsWith('touroku')?'<p class="small-note">ほかの地域の試験日と来年の準備は、<a href="/touroku-hanbaisha-nittei/">登録販売者の試験日</a>にまとめています。</p>':''}${['koko-niigata','koko-toyama','koko-ishikawa','koko-fukui'].includes(id)?'<p class="small-note">隣の県と日程を比べるときは、<a href="/hokuriku-koko-nyushi-2027/">北陸4県の公立高校入試の比較</a>が使えます。</p>':''}${String(id).startsWith('toeic')?'<p class="small-note">点数が要る日から回を選ぶには、<a href="/toeic-moshikomi-2027/">TOEICの申込締切と結果が出る日の一覧</a>が使えます。</p>':''}${['takken','gyosei','sharoshi','kaigo','nurse','boki','boki-173','boki-175','boki-net-2026','itpassport-cbt','fe-cbt'].includes(id)?'<p class="small-note">この試験の合格率は、最新の回とひとつ前の回を、<a href="/goukaku-ritsu/">合格率の見方と一覧</a>で比べられます。</p>':''}${verified.field==='大学入試'&&ownEvents.some(e=>e.type==='deadline')?'<p class="small-note">郵送で出す書類は、「必着」か「消印有効」かで、間に合う日が変わります。読み方は、<a href="/nyugaku-tetsuzuki/">入学手続の特集の「消印有効と必着の違い」</a>にあります。</p>':''}${futureHtml(id)}${ownEvents.length?`<details class="ed-date-tools"><summary>日程をカレンダーに表示・予定ファイルを保存する</summary><div>${ownEvents.map(e=>`<article class="ed-date-row" ${params.get('event')===e.id?'data-highlight="true"':''}><div><span class="event-type ${e.type==='deadline'?'peach':e.type==='exam'?'mint':'lavender'}">${esc(eventLabel(e))}</span><strong>${dateText(e)}</strong>${e.note?`<small>${esc(e.note)}</small>`:''}${eventSourceHtml(e)}</div><div><button class="quiet-button" data-calendar-event="${e.id}">カレンダーに表示</button><button class="text-button" data-ics="${e.id}">予定ファイルを保存</button></div></article>`).join('')}</div><p class="small-note">予定ファイルには確認日も添えています。申し込みや通知の予約は行われません。</p></details>`:''}</section>`;
}
